commands = [
    {'id': 'file.save', 'title': 'File: Save', 'keys': 'ctrl+s'},
    {'id': 'file.open', 'title': 'File: Open', 'keys': 'ctrl+o'},
    {'id': 'edit.find', 'title': 'Edit: Find', 'keys': 'ctrl+f'},
]

def palette(query):
    q = query.lower()
    return [c for c in commands if q in c['title'].lower()]

for q in ('save', 'file'):
    print('> %s' % q)
    for c in palette(q):
        print('  %-14s %s' % (c['title'], c['keys']))
print('every action searchable: discoverability for keyboard-first users')

def fuzzy(pat, text):
    score, pi, consec = 0, 0, 0
    for i, ch in enumerate(text):
        if pi < len(pat) and ch.lower() == pat[pi].lower():
            bonus = 15 if i == 0 or text[i-1] in ' :_-' else 0
            score += 10 + bonus + 5 * consec
            consec += 1
            pi += 1
        else:
            consec = 0
    return score if pi == len(pat) else -1

titles = ['File: Save', 'File: Save As', 'View: Save Layout', 'Edit: Find']
ranked = sorted(((fuzzy('sav', t), t) for t in titles), reverse=True)
for s, t in ranked:
    print('%-16s score %d' % (t, s))
print('boundary + consecutive bonuses: "sav" finds Save before Save Layout')

# shortcut map: checked for conflicts at build time
shortcuts = {'ctrl+s': 'save', 'ctrl+o': 'open', 'ctrl+f': 'find', 'ctrl+k': 'palette'}

def check_conflicts(m):
    seen = {}
    for keys, cmd in m.items():
        if keys in seen:
            return 'CONFLICT: %s for both %s and %s' % (keys, seen[keys], cmd)
        seen[keys] = cmd
    return 'no conflicts (%d shortcuts)' % len(m)

print(check_conflicts(shortcuts))
