registry = {}

def register(cmd_id, title, keys, when, handler):
    registry[cmd_id] = {'title': title, 'keys': keys, 'when': when, 'run': handler}

register('file.save', 'File: Save', 'ctrl+s', lambda ctx: True, lambda: 'saved!')
register('edit.find', 'Edit: Find', 'ctrl+f', lambda ctx: ctx.get('editor'), lambda: 'find...')

ctx = {'editor': True}
visible = [c for c in registry.values() if c['when'](ctx)]
print('visible commands:', [c['title'] for c in visible])
print('execute by id:', registry['file.save']['run']())
print('one registry -> menus, palette, toolbar, shortcuts stay consistent')

registry, loaded = {}, set()

def declare(plugin, cmds):
    for cid, title in cmds:
        registry['%s:%s' % (plugin, cid)] = {'title': '%s: %s' % (plugin, title), 'plugin': plugin}

def execute(cmd_id):
    plugin = registry[cmd_id]['plugin']
    if plugin not in loaded:
        loaded.add(plugin)
        print('(lazy-loaded plugin: %s)' % plugin)
    return 'ran ' + registry[cmd_id]['title']

declare('Git', [('commit', 'Commit'), ('push', 'Push')])
declare('Docker', [('ps', 'List containers')])
print(execute('Git:commit'))
print('namespaced, lazy, sandboxed: plugins extend without endangering the core')

# theme tokens drive the palette; no hardcoded colors
theme = {'bg': '#1e1e1e', 'fg': '#d4d4d4', 'accent': '#007acc', 'border': '#3c3c3c'}

def render_palette(theme):
    assert all(v.startswith('#') for v in theme.values()), 'tokens must be colors'
    return 'palette(bg=%s, selected=%s)' % (theme['bg'], theme['accent'])

print(render_palette(theme))
