# every modality normalizes to (command, args): the registry doesn't care how
def from_voice(transcript):
    return ('file.save', {}) if 'save' in transcript else (None, {})

def from_gesture(name):
    return {'swipe-down': ('file.save', {})}.get(name, (None, {}))

def from_text(q):
    return ('file.save', {}) if q.strip() == 'save' else (None, {})

for src, res in (('voice "save the file"', from_voice('save the file')),
                 ('gesture swipe-down', from_gesture('swipe-down')),
                 ('typed "save"', from_text('save'))):
    print('%-22s -> %s' % (src, res[0] or 'no match'))
print('destructive commands: confirm regardless of modality')

